metadata.script:
		let base = "visayas/cebuano";
		__local.showNote = async (header, note) => {
			
			let i = getElementById("note");
			if (note) {
				getElementById("skrol").scrollTop = 0;;
				let cacheTest = cache.getCache("files/" + base + "/" + note + ".xml");
				let e = "";
				if (cacheTest) {
					e = cacheTest;
				} else {
					let ea = await load("files/" + base + "/" + note + ".xml");
					cache.setCache("files/" + base + "/" + note + ".xml", ea);
					e = ea;
				}
				i.innerHTML = e;
			}
			getElementById("header-title").innerHTML = (header || "").trim() + " - Cebuano";
			let container = getElementById("note-container");
			container.style.opacity = "100%";
			
			container.style.pointerEvents = "auto";
			container.style.animation = "fade-in 0.2s 1 linear";
			let win = getElementById("note-window");
			win.style.width = win.style.height = "calc(100% - 1em)";
		}
		__local.hideNote = () => {
			let container = getElementById("note-container");
			container.style.opacity = "0%";
			container.style.pointerEvents = "none";
			container.style.animation = "fade-out 0.2s 1 linear";
			let win = getElementById("note-window");
			win.style.width = win.style.height = "0%";
		}
		let listenResize = (ev) => {
			setTimeout(() => {
				let grid = getElementById("bg");
				let aspectRatio = 16 / 9;
				let width = contentSize.width;
				let height = contentSize.height;
				//let aspectRatio = 25 / 20;
				let mult = 0.85;
				//grid.style.width = width + "px";

				content.style.overflowY = "hidden";
				content.style.overflowX = "hidden";
				let kh = 0;



				let portraitWidth = height * aspectRatio;
				let portraitHeight = height;
				let landscapeHeight = width;
				let landscapeWidth = width * aspectRatio;

				if (width < height) {
					grid.style.width = ~~(portraitWidth) + "px";
					grid.style.height = ~~(portraitHeight) + "px";

				} else {
					grid.style.width = ~~(landscapeWidth) + "px";
					grid.style.height = ~~(landscapeHeight) + "px";
				}





				//console.log(kk)

			}, 100);

		};
		listenResize();
		window.addEventListener("resize", listenResize, false);
		addOnLeave(() => {
			window.removeEventListener("resize", listenResize, false);
		});
		
		let buttons =[["Demographics", "demographics"], ["History", "history"], ["Culture and Festivities", "culture"], ["Customs", "customs"], ["Language", "language"]];
		
		for (let h of buttons) {
			/**
			 * 


				
			
 			*/
 			let m = document.createElement("debb");
 			m.style="float:right; position:relative;background:#50a8;width:100%;height:2em; display:flex;flex-direction:column;justify-content:center;align-items:right;margin-top:0.2em;padding-left:0em;clip-path:polygon(0% 0%, 100% 0%, 100% 100%, 5% 100%)";
 			m.onclick=() => {
 			__local.showNote(h[0], h[1]);
 			}
 			//m.style.marginLeft= "calc(0)";
 			m.onmouseover=() => {
 			m.style.background='#a0fa';
 			}
 			m.onmouseout=() => {
 			m.style.background='#50a8';
 			}
 			let k = document.createElement("te");
 			m.append(k);
 			k.style="font-family:helvetica;font-weight:bold;color:#fff;font-size:1.2em;";
 			k.innerHTML="&nbsp&nbsp&nbsp&nbsp"+h[0];
 			
 			getElementById("lm").appendChild(m);
 			
 			
		}
